generateCartFromNegotiableQuote.example:
```js
import { generateCartFromNegotiableQuote } from '@dropins/storefront-quote-management/api.js';

try {
  const cartId = await generateCartFromNegotiableQuote('quote-123');
  console.log('Cart created:', cartId);
  // Redirect to checkout
  window.location.href = `/checkout?cartId=${cartId}`;
} catch (error) {
  console.error('Failed to generate cart:', error);
}
```

negotiableQuotes.example:
```js
import { negotiableQuotes } from '@dropins/storefront-quote-management/api.js';

try {
  const result = await negotiableQuotes({
    filter: {
      name: {
        match: 'Office Supplies',
        match_type: 'PARTIAL'
      }
    },
    pageSize: 25,
    currentPage: 1,
    sort: {
      sort_field: 'CREATED_AT',
      sort_direction: 'DESC'
    }
  });
  console.log('Quotes:', result.items);
  console.log('Pagination:', result.pageInfo);
} catch (error) {
  console.error('Failed to get quotes list:', error);
}
```

requestNegotiableQuote.example:
```js
import { requestNegotiableQuote } from '@dropins/storefront-quote-management/api.js';

try {
  const quote = await requestNegotiableQuote({
    cartId: 'cart-123',
    quoteName: 'Q1 2024 Office Supplies',
    comment: 'Please provide volume discount pricing',
    isDraft: false
  });

  console.log('Quote created:', quote);
} catch (error) {
  console.error('Failed to create quote:', error);
}
```

