  console.log('Quote requested:', data.quote);
});

events.on('quote-management/quote-data', (data) => {
  console.log('Quote data updated:', data.quote);
});

events.on('quote-management/quote-data/initialized', (data) => {
  console.log('Quote initialized:', data.quote);
});
